"""Retain the reserved lake background, distinct music and six verified foreground photographs."""
from pathlib import Path
import json,subprocess,urllib.parse
ROOT=Path(__file__).resolve().parents[3];PROD=Path(__file__).resolve().parent;OLD=ROOT/'studio/production/hb-c10';SID='hb-c11-naturens-sakerhet';EP=ROOT/'studio/episodes'/SID;S=ROOT/'studio/media'/SID/'sources';S.mkdir(parents=True,exist_ok=True)
def pages(path):return {p['title']:p for p in json.loads(path.read_text()).get('query',{}).get('pages',{}).values() if 'imageinfo' in p}
def fetch(pi,path):
    url=pi.get('thumburl',pi['url']).replace('https://thumb.wikimedia.org/','https://upload.wikimedia.org/').split('?')[0]
    subprocess.run([str(ROOT/'.venv/bin/python'),str(ROOT/'studio/production/remaining/download.py'),'--url',url,'--output',str(path),'--timeout','300'],check=True);return url
ice=pages(OLD/'c11-ice-research.json');bg=ice['File:Kuusijärvi in Vantaa, Finland, 2021 February.jpg'];pi=bg['imageinfo'][0];pi['download_url']=fetch(pi,S/'background.jpg')
track=next(t for t in json.loads(Path('/tmp/c07-employment-music-catalogue.json').read_text()) if t.get('isrc')=='USUAN1100676');url='https://incompetech.com/music/royalty-free/mp3-royaltyfree/'+urllib.parse.quote(track['filename']);subprocess.run([str(ROOT/'.venv/bin/python'),str(ROOT/'studio/production/remaining/download.py'),'--url',url,'--output',str(S/'music.mp3'),'--timeout','300'],check=True)
(EP/'media-sources.json').write_text(json.dumps(dict(photo_title=bg['title'],photo=pi,music=track,context='Verified Kuusijärvi in Vantaa in February2021. Decorative Finnish winter lake setting only; the image does not establish bearing capacity or endorse travel on its ice.'),ensure_ascii=False,indent=2)+'\n')
paddle=pages(PROD/'paddling-research.json');picks=pages(PROD/'ice-picks-research.json');choices={0:(paddle['File:Kayaking in Wanha Witonen (1).jpg'],'Verified kayak and canoe on Jämsänvesi, Wanha Witonen route; illustrative Finnish boating, not navigation guidance.'),1:(paddle['File:Kayaking in Isojärvi 1.jpg'],'Verified kayaking on Isojärvi; one source-listed activity, not a claim about sailing or equipment compliance.'),4:(ice['File:Puruvesi ice ski tracks.jpg'],'Verified ski tracks on Lake Puruvesi ice; illustrates frozen waters without any assurance of current ice safety.'),5:(ice['File:Ice fishing on Lake Saimaa.jpg'],'Verified ice fishing on Lake Saimaa near Lappeenranta; activity illustration only, no assurance of ice safety.'),6:(ice['File:Hole in the ice on Vatioja in Muonio, Finland, 2019 January.jpg'],'Verified hole in frozen Vatioja pond, Muonio; visible open water illustrates source ice risk, without a thickness threshold.'),12:(picks['File:Ice Picks 20070128 001.jpg'],'Actual ice-rescue picks photographed in Sweden, not climbing axes; object illustration, no claim the photograph was taken in Finland.')};out={}
for idx,(p,context) in choices.items():
    pi=p['imageinfo'][0];dest=S/f'foreground-{idx+1:02}.jpg';url=fetch(pi,dest);out[str(idx)]=dict(title=p['title'],imageinfo=pi,path=str(dest.relative_to(ROOT)),download_url=url,context=context)
(EP/'selected-photos.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
